Index: proyecto/06_codigo/src/app.js
===================================================================
--- proyecto/06_codigo/src/app.js	
+++ proyecto/06_codigo/src/app.js	
@@ -0,0 +1,21 @@
+import express from 'express';
+import { notFoundHandler, errorHandler } from './shared/http/errors.js';
+
+export function createApp({ config, pingDb }) {
+  const app = express();
+  app.disable('x-powered-by');
+  app.use(express.json({ limit: '100kb' }));
+
+  app.get('/api/v1/health', async (_req, res) => {
+    try {
+      await pingDb();
+      res.json({ status: 'ok', version: config.version, checks: { db: 'ok' } });
+    } catch {
+      res.status(503).json({ status: 'error', version: config.version, checks: { db: 'error' } });
+    }
+  });
+
+  app.use(notFoundHandler);
+  app.use(errorHandler);
+  return app;
+}

Index: proyecto/06_codigo/src/config/env.js
===================================================================
--- proyecto/06_codigo/src/config/env.js	
+++ proyecto/06_codigo/src/config/env.js	
@@ -0,0 +1,29 @@
+import { readFileSync } from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import dotenv from 'dotenv';
+
+const here = path.dirname(fileURLToPath(import.meta.url));
+const rootDir = path.resolve(here, '../../../..');
+dotenv.config({ path: path.join(rootDir, '.env') });
+
+const pkg = JSON.parse(readFileSync(path.join(rootDir, 'proyecto/06_codigo/package.json'), 'utf8'));
+
+export function loadConfig() {
+  const password = process.env.DB_PASSWORD_APP_RW || null;
+  if (!password) {
+    console.warn('[config] Falta DB_PASSWORD_APP_RW en .env: /health reportara db=error (cuenta app_rw requerida; sin fallback a devcode)');
+  }
+  return {
+    version: pkg.version,
+    port: Number(process.env.PORT || 3001),
+    db: {
+      host: process.env.DB_HOST || '127.0.0.1',
+      port: Number(process.env.DB_PORT || 3306),
+      database: process.env.DB_NAME || 'gestion_citas_db',
+      user: process.env.APP_RW_USER || 'app_rw',
+      password,
+      timezone: process.env.DB_TIMEZONE || '+00:00',
+    },
+  };
+}

Index: proyecto/06_codigo/src/server.js
===================================================================
--- proyecto/06_codigo/src/server.js	
+++ proyecto/06_codigo/src/server.js	
@@ -0,0 +1,19 @@
+import { loadConfig } from './config/env.js';
+import { createPool, ping } from './shared/db/pool.js';
+import { createApp } from './app.js';
+
+const config = loadConfig();
+const pool = createPool(config.db);
+const app = createApp({ config, pingDb: () => ping(pool) });
+
+const server = app.listen(config.port, '127.0.0.1', () => {
+  console.log(`[server] escuchando en http://127.0.0.1:${config.port} (modo local, sin auth)`);
+});
+
+async function shutdown() {
+  server.close();
+  await pool.end();
+  process.exit(0);
+}
+process.on('SIGINT', shutdown);
+process.on('SIGTERM', shutdown);

Index: proyecto/06_codigo/src/shared/db/pool.js
===================================================================
--- proyecto/06_codigo/src/shared/db/pool.js	
+++ proyecto/06_codigo/src/shared/db/pool.js	
@@ -0,0 +1,19 @@
+import mysql from 'mysql2/promise';
+
+export function createPool(dbConfig) {
+  return mysql.createPool({
+    host: dbConfig.host,
+    port: dbConfig.port,
+    user: dbConfig.user,
+    password: dbConfig.password || undefined,
+    database: dbConfig.database,
+    waitForConnections: true,
+    connectionLimit: 5,
+    timezone: dbConfig.timezone,
+    namedPlaceholders: true,
+  });
+}
+
+export async function ping(pool) {
+  await pool.query('SELECT 1');
+}

Index: proyecto/06_codigo/src/shared/http/errors.js
===================================================================
--- proyecto/06_codigo/src/shared/http/errors.js	
+++ proyecto/06_codigo/src/shared/http/errors.js	
@@ -0,0 +1,34 @@
+export class AppError extends Error {
+  constructor(message, { status = 500, code = 'INTERNAL_ERROR', details = undefined } = {}) {
+    super(message);
+    this.status = status;
+    this.code = code;
+    this.details = details;
+  }
+}
+
+export class ValidationError extends AppError {
+  constructor(message, details) {
+    super(message, { status: 400, code: 'VALIDATION_ERROR', details });
+  }
+}
+
+export class NotFoundError extends AppError {
+  constructor(message = 'Recurso no encontrado') {
+    super(message, { status: 404, code: 'NOT_FOUND' });
+  }
+}
+
+export function notFoundHandler(_req, res) {
+  res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Ruta no encontrada' } });
+}
+
+export function errorHandler(err, _req, res, _next) {
+  if (err instanceof AppError) {
+    return res.status(err.status).json({
+      error: { code: err.code, message: err.message, ...(err.details ? { details: err.details } : {}) },
+    });
