import { ValidationError } from '../../../shared/http/errors.js';

const ESTADOS = new Set(['activo', 'inactivo']);

export function parseEstadoQuery(valor) {
  if (valor === undefined || valor === '') return undefined;
  if (!ESTADOS.has(valor)) {
    throw new ValidationError("Parámetro 'estado' inválido: use 'activo' o 'inactivo'", { parametro: 'estado' });
  }
  return valor;
}

export function toServicio(row) {
  return {
    id: row.id,
    nombre: row.nombre,
    descripcion: row.descripcion,
    duracion_minutos: row.duracion_minutos,
    estado: row.estado,
  };
}

import { toServicio } from '../domain/servicio.js';

export function crearListarServicios({ servicioRepository }) {
  return async function listarServicios({ estado } = {}) {
    const filas = await servicioRepository.findAll({ estado });
    return filas.map(toServicio);
  };
}

import { AppError } from '../../../../shared/http/errors.js';

const SQL_LISTAR = `SELECT id, nombre, descripcion, duracion_minutos, estado
  FROM servicio
 WHERE (:estado IS NULL OR estado = :estado)
 ORDER BY id`;

export class MysqlServicioRepository {
  #pool;
  constructor(pool) {
    this.#pool = pool;
  }

  async findAll({ estado } = {}) {
    try {
      const [rows] = await this.#pool.execute(SQL_LISTAR, { estado: estado ?? null });
      return rows;
    } catch (err) {
      console.error('[catalogo] error SQL en findAll:', err.message);
      throw new AppError('Error al consultar servicios', { status: 500, code: 'DB_ERROR' });
    }
  }
}

export class InMemoryServicioRepository {
  #filas;
  constructor(filas = []) {
    this.#filas = filas.map((f) => ({ ...f }));
  }

  async findAll({ estado } = {}) {
    if (estado === undefined) return this.#filas.map((f) => ({ ...f }));
    return this.#filas.filter((f) => f.estado === estado).map((f) => ({ ...f }));
  }
}

import { Router } from 'express';
import { parseEstadoQuery } from '../../domain/servicio.js';

export function crearServiciosRouter({ listarServicios }) {
  const router = Router();

  router.get('/', async (req, res, next) => {
    try {
      const estado = parseEstadoQuery(req.query.estado);
      const servicios = await listarServicios({ estado });
      res.json(servicios);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

