import { ValidationError } from '../../../shared/http/errors.js';

const ESTADOS = new Set(['activo', 'inactivo']);
const MAX_NOMBRE = 100;
const MAX_DESCRIPCION = 500;
const MAX_DURACION = 1440;

export function parseEstadoQuery(valor) {
  if (valor === undefined || valor === '') return undefined;
  if (!ESTADOS.has(valor)) {
    throw new ValidationError("Parámetro 'estado' inválido: use 'activo' o 'inactivo'", { parametro: 'estado' });
  }
  return valor;
}

export function parseIdParam(valor) {
  const texto = String(valor ?? '').trim();
  if (!/^\d+$/.test(texto)) {
    throw new ValidationError("Parámetro 'id' inválido: debe ser un entero positivo", { parametro: 'id' });
  }
  const id = Number(texto);
  if (!Number.isSafeInteger(id) || id <= 0) {
    throw new ValidationError("Parámetro 'id' inválido: debe ser un entero positivo", { parametro: 'id' });
  }
  return id;
}

function validarNombre(nombre, requerido) {
  if (nombre === undefined && !requerido) {
    throw new ValidationError("El campo 'nombre' es obligatorio", { campo: 'nombre' });
  }
  if (typeof nombre !== 'string' || nombre.trim().length === 0 || nombre.trim().length > MAX_NOMBRE) {
    throw new ValidationError(`'nombre' debe ser un texto de 1 a ${MAX_NOMBRE} caracteres`, { campo: 'nombre' });
  }
  return nombre.trim();
}

function validarDescripcion(descripcion) {
  if (descripcion === undefined || descripcion === null) return null;
  if (typeof descripcion !== 'string' || descripcion.length > MAX_DESCRIPCION) {
    throw new ValidationError(`'descripcion' debe ser texto de máximo ${MAX_DESCRIPCION} caracteres o null`, { campo: 'descripcion' });
  }
  return descripcion;
}

function validarDuracion(duracion, requerido) {
  if (duracion === undefined && !requerido) {
    throw new ValidationError("El campo 'duracion_minutos' es obligatorio", { campo: 'duracion_minutos' });
  }
  if (!Number.isInteger(duracion) || duracion < 1 || duracion > MAX_DURACION) {
    throw new ValidationError(`'duracion_minutos' debe ser un entero entre 1 y ${MAX_DURACION}`, { campo: 'duracion_minutos' });
  }
  return duracion;
}

function validarEstado(estado) {
  if (!ESTADOS.has(estado)) {
    throw new ValidationError("'estado' debe ser 'activo' o 'inactivo'", { campo: 'estado' });
  }
  return estado;
}

function cuerpoObjeto(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new ValidationError('El cuerpo debe ser un objeto JSON');
  }
  return body;
}

export function parseCrearServicioBody(body) {
  const b = cuerpoObjeto(body);
  return {
    nombre: validarNombre(b.nombre, true),
    descripcion: validarDescripcion(b.descripcion),
    duracion_minutos: validarDuracion(b.duracion_minutos, true),
    estado: validarEstado(b.estado === undefined ? 'activo' : b.estado),
  };
}

export function parseActualizarServicioBody(body) {
  const b = cuerpoObjeto(body);
  return {
    nombre: validarNombre(b.nombre, true),
    descripcion: validarDescripcion(b.descripcion),
    duracion_minutos: validarDuracion(b.duracion_minutos, true),
    estado: validarEstado(b.estado === undefined ? 'activo' : b.estado),
  };
}

export function toServicio(row) {
  return {
    id: row.id,
    nombre: row.nombre,
    descripcion: row.descripcion,
    duracion_minutos: row.duracion_minutos,
    estado: row.estado,
  };
}

import { toServicio } from '../domain/servicio.js';

export function crearObtenerServicio({ servicioRepository }) {
  return async function obtenerServicio({ id }) {
    const fila = await servicioRepository.findById(id);
    return fila ? toServicio(fila) : null;
  };
}

export function crearCrearServicio({ servicioRepository }) {
  return async function crearServicio({ datos }) {
    const fila = await servicioRepository.create(datos);
    return toServicio(fila);
  };
}

export function crearActualizarServicio({ servicioRepository }) {
  return async function actualizarServicio({ id, datos }) {
    const fila = await servicioRepository.update(id, datos);
    return fila ? toServicio(fila) : null;
  };
}

export function crearDesactivarServicio({ servicioRepository }) {
  return async function desactivarServicio({ id }) {
    const fila = await servicioRepository.setState(id, 'inactivo');
    return fila ? toServicio(fila) : null;
  };
}

import { AppError } from '../../../../shared/http/errors.js';

const SQL_LISTAR = `SELECT id, nombre, descripcion, duracion_minutos, estado
  FROM servicio
 WHERE (:estado IS NULL OR estado = :estado)
 ORDER BY id`;

const SQL_POR_ID = `SELECT id, nombre, descripcion, duracion_minutos, estado
  FROM servicio
 WHERE id = :id`;

const SQL_CREAR = `INSERT INTO servicio (nombre, descripcion, duracion_minutos, estado)
VALUES (:nombre, :descripcion, :duracion_minutos, :estado)`;

const SQL_ACTUALIZAR = `UPDATE servicio
   SET nombre = :nombre, descripcion = :descripcion, duracion_minutos = :duracion_minutos, estado = :estado
 WHERE id = :id`;

const SQL_CAMBIAR_ESTADO = `UPDATE servicio SET estado = :estado WHERE id = :id`;

export class MysqlServicioRepository {
  #pool;
  constructor(pool) {
    this.#pool = pool;
  }

  async #ejecutar(sql, params) {
    try {
      return await this.#pool.execute(sql, params);
    } catch (err) {
      console.error('[catalogo] error SQL:', err.message);
      throw new AppError('Error al consultar servicios', { status: 500, code: 'DB_ERROR' });
    }
  }

  async findAll({ estado } = {}) {
    const [rows] = await this.#ejecutar(SQL_LISTAR, { estado: estado ?? null });
    return rows;
  }

  async findById(id) {
    const [rows] = await this.#ejecutar(SQL_POR_ID, { id });
    return rows[0] ?? null;
  }

  async create(datos) {
    const [result] = await this.#ejecutar(SQL_CREAR, datos);
    return this.findById(result.insertId);
  }

  async update(id, datos) {
    const existe = await this.findById(id);
    if (!existe) return null;
    await this.#ejecutar(SQL_ACTUALIZAR, { ...datos, id });
    return this.findById(id);
  }

  async setState(id, estado) {
    const existe = await this.findById(id);
    if (!existe) return null;
    await this.#ejecutar(SQL_CAMBIAR_ESTADO, { id, estado });
    return this.findById(id);
  }
}

export class InMemoryServicioRepository {
  #filas;
  #siguienteId;
  constructor(filas = []) {
    this.#filas = filas.map((f) => ({ ...f }));
    this.#siguienteId = this.#filas.reduce((max, f) => Math.max(max, f.id), 0) + 1;
  }

  async findAll({ estado } = {}) {
    const filas = estado === undefined ? this.#filas : this.#filas.filter((f) => f.estado === estado);
    return filas.map((f) => ({ ...f }));
  }

  async findById(id) {
    const fila = this.#filas.find((f) => f.id === id);
    return fila ? { ...fila } : null;
  }

  async create(datos) {
    const fila = { id: this.#siguienteId++, ...datos };
    this.#filas.push(fila);
    return { ...fila };
  }

  async update(id, datos) {
    const fila = this.#filas.find((f) => f.id === id);
    if (!fila) return null;
    Object.assign(fila, datos);
    return { ...fila };
  }

  async setState(id, estado) {
    const fila = this.#filas.find((f) => f.id === id);
    if (!fila) return null;
    fila.estado = estado;
    return { ...fila };
  }
}

import { Router } from 'express';
import {
  parseEstadoQuery,
  parseIdParam,
  parseCrearServicioBody,
  parseActualizarServicioBody,
} from '../../domain/servicio.js';
import { NotFoundError } from '../../../../shared/http/errors.js';

export function crearServiciosRouter({
  listarServicios,
  obtenerServicio,
  crearServicio,
  actualizarServicio,
  desactivarServicio,
}) {
  const router = Router();

  router.get('/', async (req, res, next) => {
    try {
      const estado = parseEstadoQuery(req.query.estado);
      res.json(await listarServicios({ estado }));
    } catch (err) {
      next(err);
    }
  });

  router.get('/:id', async (req, res, next) => {
    try {
      const id = parseIdParam(req.params.id);
      const servicio = await obtenerServicio({ id });
      if (!servicio) throw new NotFoundError('Servicio no encontrado');
      res.json(servicio);
    } catch (err) {
      next(err);
    }
  });

  router.post('/', async (req, res, next) => {
    try {
      const datos = parseCrearServicioBody(req.body);
      const servicio = await crearServicio({ datos });
      res.status(201).json(servicio);
    } catch (err) {
      next(err);
    }
  });

  router.put('/:id', async (req, res, next) => {
    try {
      const id = parseIdParam(req.params.id);
      const datos = parseActualizarServicioBody(req.body);
      const servicio = await actualizarServicio({ id, datos });
      if (!servicio) throw new NotFoundError('Servicio no encontrado');
      res.json(servicio);
    } catch (err) {
      next(err);
    }
  });

  router.delete('/:id', async (req, res, next) => {
    try {
      const id = parseIdParam(req.params.id);
      const servicio = await desactivarServicio({ id });
      if (!servicio) throw new NotFoundError('Servicio no encontrado');
      res.json(servicio);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

