import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

const N = 16384;
const R = 8;
const P = 1;
const KEYLEN = 64;
const LONGITUD_MINIMA = 12;
const LONGITUD_MAXIMA = 200;

export function hashPassword(password) {
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, KEYLEN, { N, R, P }).toString('hex');
  return `scrypt$${N}$${R}$${P}$${salt}$${hash}`;
}

export function verifyPassword(password, almacenado) {
  try {
    const partes = String(almacenado ?? '').split('$');
    if (partes.length !== 6 || partes[0] !== 'scrypt') return false;
    const [, n, r, p, salt, hashHex] = partes;
    const esperado = Buffer.from(hashHex, 'hex');
    const calculado = scryptSync(String(password), salt, esperado.length, {
      N: Number(n), R: Number(r), P: Number(p),
    });
    return timingSafeEqual(esperado, calculado);
  } catch {
    return false;
  }
}

export function passwordSeguraValida(password) {
  return typeof password === 'string' && password.length >= LONGITUD_MINIMA && password.length <= LONGITUD_MAXIMA;
}

export const HASH_FANTASMA = hashPassword(randomBytes(16).toString('hex'));

export function ahoraUtcMysql(fecha = new Date()) {
  const iso = fecha.toISOString();
  return `${iso.slice(0, 19).replace('T', ' ')}${iso.slice(23)}`;
}

export function minutosDesdeUtc(instanteUtcMysql, ahora = new Date()) {
  const normalizado = String(instanteUtcMysql).replace(' ', 'T') + (String(instanteUtcMysql).includes('.') ? '' : '.000');
  return (ahora.getTime() - new Date(`${normalizado}Z`).getTime()) / 60000;
}

import { ValidationError } from '../../../shared/http/errors.js';

const ROLES = new Set(['solicitante', 'profesional', 'administrador']);

export function parseLoginBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new ValidationError('El cuerpo debe ser un objeto JSON');
  }
  const correo = typeof body.correo === 'string' ? body.correo.trim().toLowerCase() : '';
  if (!correo || correo.length > 254 || !correo.includes('@')) {
    throw new ValidationError("'correo' debe ser un correo electrónico válido", { campo: 'correo' });
  }
  const contrasena = body.contrasena;
  if (typeof contrasena !== 'string' || contrasena.length === 0 || contrasena.length > 1024) {
    throw new ValidationError("'contrasena' es obligatoria", { campo: 'contrasena' });
  }
  return { correo, contrasena };
}

export function toUsuarioSeguro(row) {
  return {
    id: row.id,
    nombre_completo: row.nombre_completo,
    correo: row.correo,
    rol: row.rol,
  };
}

export function esRolValido(rol) {
  return ROLES.has(rol);
}

import { HASH_FANTASMA, verifyPassword } from '../../../shared/security/passwords.js';
import { AppError } from '../../../shared/http/errors.js';
import { toUsuarioSeguro } from '../domain/usuario.js';

export function crearLogin({ usuarioRepository, sesionStore, rateLimiter }) {
  return async function login({ correo, contrasena }) {
    const acceso = rateLimiter.intentar(correo);
    if (!acceso.permitido) {
      throw new AppError('Demasiados intentos. Intente más tarde.', { status: 429, code: 'RATE_LIMITED' });
    }
    const fila = await usuarioRepository.findByCorreo(correo);
    const hash = fila?.hash_contrasena ?? HASH_FANTASMA;
    const coincide = verifyPassword(contrasena, hash);
    if (!fila || !coincide || fila.estado !== 'activo') {
      rateLimiter.registrarFallo(correo);
      throw new AppError('Credenciales inválidas', { status: 401, code: 'UNAUTHORIZED' });
    }
    rateLimiter.registrarExito(correo);
    const token = sesionStore.crear({
      usuarioId: fila.id,
      nombre_completo: fila.nombre_completo,
      correo: fila.correo,
      rol: fila.rol,
    });
    return { token, usuario: toUsuarioSeguro(fila) };
  };
}

export function crearLogout({ sesionStore }) {
  return async function logout({ token }) {
    sesionStore.revocar(token);
  };
}

export function crearObtenerSesion({ usuarioRepository }) {
  return async function obtenerSesion({ usuarioId }) {
    const fila = await usuarioRepository.findById(usuarioId);
    if (!fila || fila.estado !== 'activo') return null;
    return toUsuarioSeguro(fila);
  };
}

const SQL_POR_CORREO = `SELECT id, nombre_completo, correo, hash_contrasena, rol, estado
  FROM usuario
 WHERE correo = :correo`;

const SQL_POR_ID = `SELECT id, nombre_completo, correo, hash_contrasena, rol, estado
  FROM usuario
 WHERE id = :id`;

import { AppError } from '../../../../shared/http/errors.js';

export class MysqlUsuarioRepository {
  #pool;
  constructor(pool) {
    this.#pool = pool;
  }

  async #ejecutar(sql, params) {
    try {
      const [rows] = await this.#pool.execute(sql, params);
      return rows;
    } catch (err) {
      console.error('[identidad] error SQL:', err.message);
      throw new AppError('Error al consultar usuario', { status: 500, code: 'DB_ERROR' });
    }
  }

  async findByCorreo(correo) {
    const rows = await this.#ejecutar(SQL_POR_CORREO, { correo });
    return rows[0] ?? null;
  }

  async findById(id) {
    const rows = await this.#ejecutar(SQL_POR_ID, { id });
    return rows[0] ?? null;
  }
}

export class InMemoryUsuarioRepository {
  #filas;
  #siguienteId;
  constructor(filas = []) {
    this.#filas = filas.map((f) => ({ ...f }));
    this.#siguienteId = this.#filas.reduce((max, f) => Math.max(max, f.id), 0) + 1;
  }

  async findByCorreo(correo) {
    const fila = this.#filas.find((f) => f.correo === correo);
    return fila ? { ...fila } : null;
  }

  async findById(id) {
    const fila = this.#filas.find((f) => f.id === id);
    return fila ? { ...fila } : null;
  }

  async create(datos) {
    const fila = { id: this.#siguienteId++, estado: 'activo', ...datos };
    this.#filas.push(fila);
    return { ...fila };
  }
}

import { randomBytes } from 'node:crypto';

export class SesionStoreEnMemoria {
  #sesiones = new Map();
  #ttlMs;
  constructor({ ttlMinutos = 480 } = {}) {
    this.#ttlMs = ttlMinutos * 60000;
  }

  crear(datos) {
    const token = randomBytes(32).toString('hex');
    this.#sesiones.set(token, { ...datos, expiraMs: Date.now() + this.#ttlMs });
    return token;
  }

  obtener(token) {
    const sesion = this.#sesiones.get(token);
    if (!sesion) return null;
    if (sesion.expiraMs <= Date.now()) {
      this.#sesiones.delete(token);
      return null;
    }
    return { ...sesion };
  }

  revocar(token) {
    this.#sesiones.delete(token);
  }
}

export class LoginRateLimiterEnMemoria {
  #intentos = new Map();
  #maxIntentos;
  #ventanaMs;
  constructor({ maxIntentos = 5, ventanaMinutos = 15 } = {}) {
    this.#maxIntentos = maxIntentos;
    this.#ventanaMs = ventanaMinutos * 60000;
  }

  intentar(clave) {
    const estado = this.#intentos.get(clave);
    if (!estado) return { permitido: true };
    if (estado.bloqueadoHasta > Date.now()) return { permitido: false };
    return { permitido: true };
  }

  registrarFallo(clave) {
    const ahora = Date.now();
    const estado = this.#intentos.get(clave) ?? { fallos: 0, ventanaDesde: ahora, bloqueadoHasta: 0 };
    if (ahora - estado.ventanaDesde > this.#ventanaMs) {
      estado.fallos = 0;
      estado.ventanaDesde = ahora;
      estado.bloqueadoHasta = 0;
    }
    estado.fallos += 1;
    if (estado.fallos >= this.#maxIntentos) {
      estado.bloqueadoHasta = ahora + this.#ventanaMs;
    }
    this.#intentos.set(clave, estado);
  }

  registrarExito(clave) {
    this.#intentos.delete(clave);
  }
}

import { AppError } from '../../../../shared/http/errors.js';

export function crearRequireAuth({ sesionStore }) {
  return function requireAuth(req, _res, next) {
    const cabecera = req.headers.authorization ?? '';
    const token = cabecera.startsWith('Bearer ') ? cabecera.slice(7).trim() : null;
    if (!token) {
      return next(new AppError('Autenticación requerida', { status: 401, code: 'UNAUTHORIZED' }));
    }
    const sesion = sesionStore.obtener(token);
    if (!sesion) {
      return next(new AppError('Sesión inválida o expirada', { status: 401, code: 'UNAUTHORIZED' }));
    }
    req.sesion = { ...sesion, token };
    next();
  };
}

export function requerirRol(...roles) {
  return function (req, _res, next) {
    if (!req.sesion) {
      return next(new AppError('Autenticación requerida', { status: 401, code: 'UNAUTHORIZED' }));
    }
    if (!roles.includes(req.sesion.rol)) {
      return next(new AppError('No autorizado para esta operación', { status: 403, code: 'FORBIDDEN' }));
    }
    next();
  };
}

import { Router } from 'express';
import { parseLoginBody } from '../../domain/usuario.js';

export function crearAuthRouter({ login, logout, obtenerSesion, requireAuth }) {
  const router = Router();

  router.post('/login', async (req, res, next) => {
    try {
      const credenciales = parseLoginBody(req.body);
      res.json(await login(credenciales));
    } catch (err) {
      next(err);
    }
  });

  router.post('/logout', requireAuth, async (req, res, next) => {
    try {
      await logout({ token: req.sesion.token });
      res.json({ mensaje: 'Sesión finalizada' });
    } catch (err) {
      next(err);
    }
  });

  router.get('/me', requireAuth, async (req, res, next) => {
    try {
      const usuario = await obtenerSesion({ usuarioId: req.sesion.usuarioId });
      if (!usuario) {
        return next(Object.assign(new Error('Sesión inválida o expirada'), { status: 401, code: 'UNAUTHORIZED' }));
      }
      res.json(usuario);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

import express from 'express';
import { notFoundHandler, errorHandler } from './shared/http/errors.js';

export function createApp({ config, pingDb, serviciosRouter, authRouter }) {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '100kb' }));

  app.get('/api/v1/health', async (_req, res) => {
    try {
      await pingDb();
      res.json({ status: 'ok', version: config.version, checks: { db: 'ok' } });
    } catch {
      res.status(503).json({ status: 'error', version: config.version, checks: { db: 'error' } });
    }
  });

  if (authRouter) {
    app.use('/api/v1/auth', authRouter);
  }
  if (serviciosRouter) {
    app.use('/api/v1/servicios', serviciosRouter);
  }

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

