import { loadConfig } from './config/env.js';
import { createPool, ping } from './shared/db/pool.js';
import { createApp } from './app.js';
import { ahoraUtcMysql } from './shared/time/utc.js';
import { MysqlServicioRepository } from './modules/catalogo/adapters/persistence/servicio-repository-mysql.js';
import { crearListarServicios } from './modules/catalogo/application/listar-servicios.js';
import {
  crearObtenerServicio,
  crearCrearServicio,
  crearActualizarServicio,
  crearDesactivarServicio,
} from './modules/catalogo/application/servicio-casos-de-uso.js';
import { crearServiciosRouter } from './modules/catalogo/adapters/http/servicios-router.js';
import { MysqlUsuarioRepository } from './modules/identidad/adapters/persistence/usuario-repository-mysql.js';
import { SesionStoreEnMemoria, LoginRateLimiterEnMemoria } from './modules/identidad/adapters/security/sesiones-y-limite.js';
import { crearLogin, crearLogout, crearObtenerSesion } from './modules/identidad/application/auth-casos-de-uso.js';
import { crearAuthRouter } from './modules/identidad/adapters/http/auth-router.js';
import { crearRequireAuth, requerirRol } from './modules/identidad/adapters/http/auth-middleware.js';

const config = loadConfig();
const pool = createPool(config.db);

const servicioRepository = new MysqlServicioRepository(pool);
const usuarioRepository = new MysqlUsuarioRepository(pool);
const sesionStore = new SesionStoreEnMemoria({ ttlMinutos: config.sesion.ttlMinutos });
const rateLimiter = new LoginRateLimiterEnMemoria({
  maxIntentos: config.login.maxIntentos,
  ventanaMinutos: config.login.ventanaMinutos,
});

const requireAuth = crearRequireAuth({ sesionStore });
const authRouter = crearAuthRouter({
  login: crearLogin({ usuarioRepository, sesionStore, rateLimiter }),
  logout: crearLogout({ sesionStore }),
  obtenerSesion: crearObtenerSesion({ usuarioRepository }),
  requireAuth,
});

const serviciosRouter = crearServiciosRouter({
  listarServicios: crearListarServicios({ servicioRepository }),
  obtenerServicio: crearObtenerServicio({ servicioRepository }),
  crearServicio: crearCrearServicio({ servicioRepository }),
  actualizarServicio: crearActualizarServicio({ servicioRepository }),
  desactivarServicio: crearDesactivarServicio({ servicioRepository }),
  protegerMutaciones: [requireAuth, requerirRol('administrador')],
});

const app = createApp({ config, pingDb: () => ping(pool), serviciosRouter, authRouter });

export { app, pool, ahoraUtcMysql };

if (process.env.NODE_ENV !== 'test' && !process.argv[1]?.includes('test')) {
  const server = app.listen(config.port, '127.0.0.1', () => {
    console.log(`[server] escuchando en http://127.0.0.1:${config.port} (modo local)`);
  });
  async function shutdown() {
    server.close();
    await pool.end();
    process.exit(0);
  }
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

import { loadConfig } from '../src/config/env.js';
import { createPool } from '../src/shared/db/pool.js';
import { hashPassword, passwordSeguraValida } from '../src/shared/security/passwords.js';
import { ahoraUtcMysql } from '../src/shared/time/utc.js';

function arg(nombre) {
  const idx = process.argv.indexOf(nombre);
  return idx >= 0 ? process.argv[idx + 1] : undefined;
}

const correo = (arg('--correo') || process.env.DEMO_USER_CORREO || '').trim().toLowerCase();
const nombre = arg('--nombre') || process.env.DEMO_USER_NOMBRE || 'Usuario Demo';
const contrasena = arg('--contrasena') || process.env.DEMO_USER_PASSWORD || '';
const rol = arg('--rol') || 'administrador';

if (!correo || !correo.includes('@')) {
  console.error('Uso: node tools/create_demo_user.mjs --correo <correo> [--nombre "<nombre>"] [--contrasena <password>] [--rol administrador|solicitante|profesional]');
  console.error('La contraseña también puede pasarse por DEMO_USER_PASSWORD (nunca se imprime).');
  process.exit(1);
}
if (!passwordSeguraValida(contrasena)) {
  console.error("La contraseña debe tener entre 12 y 200 caracteres (RNF-029). No se imprime ni se codifica en el repo.");
  process.exit(1);
}
if (!['solicitante', 'profesional', 'administrador'].includes(rol)) {
  console.error("Rol inválido: use solicitante, profesional o administrador.");
  process.exit(1);
}

const config = loadConfig();
const pool = createPool(config.db);

try {
  const [existentes] = await pool.execute('SELECT id FROM usuario WHERE correo = :correo', { correo });
  if (existentes.length > 0) {
    console.log(`Usuario ya existente (id=${existentes[0].id}, correo=${correo}); nada que crear.`);
    process.exit(0);
  }
  const ahora = ahoraUtcMysql();
  const [resultado] = await pool.execute(
    `INSERT INTO usuario (nombre_completo, correo, hash_contrasena, rol, estado, creado_utc, actualizado_utc)
     VALUES (:nombre, :correo, :hash, :rol, 'activo', :ahora, :ahora)`,
    { nombre, correo, hash: hashPassword(contrasena), rol, ahora },
  );
  console.log(`Usuario creado (id=${resultado.insertId}, correo=${correo}, rol=${rol}).`);
  process.exit(0);
} catch (err) {
  console.error('Error creando usuario:', err.message);
  process.exit(1);
} finally {
  await pool.end();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { hashPassword, verifyPassword, passwordSeguraValida } from '../../../src/shared/security/passwords.js';
import { ahoraUtcMysql } from '../../../src/shared/time/utc.js';

test('hashPassword genera formato scrypt con sal (sin texto plano)', () => {
  const h = hashPassword('Frase larga de prueba 2026');
  assert.match(h, /^scrypt\$16384\$8\$1\$[0-9a-f]{32}\$[0-9a-f]{128}$/);
  assert.ok(!h.includes('Frase'));
  const h2 = hashPassword('Frase larga de prueba 2026');
  assert.notEqual(h, h2, 'la sal debe diferir entre hashes');
});

test('verifyPassword valida la contraseña correcta y rechaza la incorrecta', () => {
  const h = hashPassword('Otra frase larga!! 123');
  assert.equal(verifyPassword('Otra frase larga!! 123', h), true);
  assert.equal(verifyPassword('otra frase larga!! 123', h), false);
  assert.equal(verifyPassword('', h), false);
  assert.equal(verifyPassword('x', 'hash-corrupto'), false);
  assert.equal(verifyPassword('x', null), false);
});

test('passwordSeguraValida exige 12–200 caracteres (RNF-029)', () => {
  assert.equal(passwordSeguraValida('corta'), false);
  assert.equal(passwordSeguraValida('123456789012'), true);
  assert.equal(passwordSeguraValida('x'.repeat(201)), false);
  assert.equal(passwordSeguraValida(null), false);
});

test('ahoraUtcMysql produce marca UTC con milisegundos', () => {
  const marca = ahoraUtcMysql(new Date('2026-10-09T15:30:45.123Z'));
  assert.equal(marca, '2026-10-09 15:30:45.123');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseLoginBody } from '../../../src/modules/identidad/domain/usuario.js';
import { SesionStoreEnMemoria, LoginRateLimiterEnMemoria } from '../../../src/modules/identidad/adapters/security/sesiones-y-limite.js';
import { ValidationError } from '../../../src/shared/http/errors.js';

test('parseLoginBody normaliza correo y valida campos', () => {
  assert.deepEqual(parseLoginBody({ correo: ' Admin@Demo.Org ', contrasena: 'secreta-larga-1' }), {
    correo: 'admin@demo.org',
    contrasena: 'secreta-larga-1',
  });
  for (const cuerpo of [null, [], {}, { correo: 'x', contrasena: 'y' }, { correo: 'a@b.c' }, { correo: 'a@b.c', contrasena: 5 }]) {
    assert.throws(() => parseLoginBody(cuerpo), ValidationError);
  }
});

test('SesionStoreEnMemoria crea, obtiene, expira y revoca', () => {
  const store = new SesionStoreEnMemoria({ ttlMinutos: 60 });
  const token = store.crear({ usuarioId: 1, nombre_completo: 'A', correo: 'a@b.c', rol: 'administrador' });
  assert.equal(store.obtener(token).usuarioId, 1);
  store.revocar(token);
  assert.equal(store.obtener(token), null);
});

test('SesionStoreEnMemoria expira la sesión tras el TTL', async () => {
  const store = new SesionStoreEnMemoria({ ttlMinutos: 0.0001 });
  const token = store.crear({ usuarioId: 1, nombre_completo: 'A', correo: 'a@b.c', rol: 'solicitante' });
  await new Promise((r) => setTimeout(r, 10));
  assert.equal(store.obtener(token), null);
});

test('LoginRateLimiterEnMemoria bloquea tras el máximo de fallos y limpia con el éxito', () => {
  const limiter = new LoginRateLimiterEnMemoria({ maxIntentos: 2, ventanaMinutos: 15 });
  assert.equal(limiter.intentar('u@x.y').permitido, true);
  limiter.registrarFallo('u@x.y');
  assert.equal(limiter.intentar('u@x.y').permitido, true);
  limiter.registrarFallo('u@x.y');
  assert.equal(limiter.intentar('u@x.y').permitido, false);
  assert.equal(limiter.intentar('otro@x.y').permitido, true, 'el límite es por correo');
  limiter.registrarExito('u@x.y');
  assert.equal(limiter.intentar('u@x.y').permitido, true);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { createApp } from '../../src/app.js';
import { hashPassword } from '../../src/shared/security/passwords.js';
import { InMemoryServicioRepository } from '../../src/modules/catalogo/adapters/persistence/servicio-repository-in-memory.js';
import { InMemoryUsuarioRepository } from '../../src/modules/identidad/adapters/persistence/usuario-repository-in-memory.js';
import { SesionStoreEnMemoria, LoginRateLimiterEnMemoria } from '../../src/modules/identidad/adapters/security/sesiones-y-limite.js';
import { crearListarServicios } from '../../src/modules/catalogo/application/listar-servicios.js';
import {
  crearObtenerServicio,
  crearCrearServicio,
  crearActualizarServicio,
  crearDesactivarServicio,
} from '../../src/modules/catalogo/application/servicio-casos-de-uso.js';
import { crearServiciosRouter } from '../../src/modules/catalogo/adapters/http/servicios-router.js';
import { crearLogin, crearLogout, crearObtenerSesion } from '../../src/modules/identidad/application/auth-casos-de-uso.js';
import { crearAuthRouter } from '../../src/modules/identidad/adapters/http/auth-router.js';
import { crearRequireAuth, requerirRol } from '../../src/modules/identidad/adapters/http/auth-middleware.js';

const config = { version: 'test', sesion: { ttlMinutos: 60 }, login: { maxIntentos: 5, ventanaMinutos: 15 } };
const PASS_ADMIN = 'AdminDemo.2026!!';
const PASS_SOLI = 'SolicitanteDemo.26!';

function crearBase() {
  const usuarios = new InMemoryUsuarioRepository([
    { id: 1, nombre_completo: 'Ada Admin', correo: 'admin@citas.demo', hash_contrasena: hashPassword(PASS_ADMIN), rol: 'administrador', estado: 'activo' },
    { id: 2, nombre_completo: 'Sol Solicitante', correo: 'soli@citas.demo', hash_contrasena: hashPassword(PASS_SOLI), rol: 'solicitante', estado: 'activo' },
    { id: 3, nombre_completo: 'Ina Inactiva', correo: 'ina@citas.demo', hash_contrasena: hashPassword(PASS_ADMIN), rol: 'solicitante', estado: 'inactivo' },
  ]);
  const servicios = new InMemoryServicioRepository([
    { id: 1, nombre: 'Consulta general', descripcion: null, duracion_minutos: 30, estado: 'activo' },
  ]);
  const sesionStore = new SesionStoreEnMemoria({ ttlMinutos: 60 });
  const rateLimiter = new LoginRateLimiterEnMemoria({ maxIntentos: 5, ventanaMinutos: 15 });
  const requireAuth = crearRequireAuth({ sesionStore });
  const app = createApp({
    config,
    pingDb: async () => {},
    authRouter: crearAuthRouter({
      login: crearLogin({ usuarioRepository: usuarios, sesionStore, rateLimiter }),
      logout: crearLogout({ sesionStore }),
      obtenerSesion: crearObtenerSesion({ usuarioRepository: usuarios }),
      requireAuth,
    }),
    serviciosRouter: crearServiciosRouter({
      listarServicios: crearListarServicios({ servicioRepository: servicios }),
      obtenerServicio: crearObtenerServicio({ servicioRepository: servicios }),
      crearServicio: crearCrearServicio({ servicioRepository: servicios }),
      actualizarServicio: crearActualizarServicio({ servicioRepository: servicios }),
      desactivarServicio: crearDesactivarServicio({ servicioRepository: servicios }),
      protegerMutaciones: [requireAuth, requerirRol('administrador')],
    }),
  });
  const server = http.createServer(app);
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      resolve({ server, base: `http://127.0.0.1:${server.address().port}`, rateLimiter });
    });
  });
}

async function login(base, correo, contrasena) {
  const res = await fetch(`${base}/api/v1/auth/login`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ correo, contrasena }),
  });
  return { res, body: await res.json() };
}

// ---------- CP-BACK-03: login ----------

test('login con credenciales válidas devuelve token y usuario seguro (sin hash)', async () => {
  const { server, base } = await crearBase();
  try {
    const { res, body } = await login(base, 'admin@citas.demo', PASS_ADMIN);
    assert.equal(res.status, 200);
    assert.ok(body.token && body.token.length >= 64);
    assert.equal(body.usuario.rol, 'administrador');
    assert.equal(body.usuario.hash_contrasena, undefined);
    assert.equal(body.contrasena, undefined);
  } finally {
    server.close();
  }
});

test('login con credenciales inválidas responde 401 con mensaje genérico (mismo mensaje para correo inexistente)', async () => {
  const { server, base } = await crearBase();
  try {
    const mala = await login(base, 'admin@citas.demo', 'password-equivocada-1');
    assert.equal(mala.res.status, 401);
    assert.equal(mala.body.error.code, 'UNAUTHORIZED');
    const inexistente = await login(base, 'nadie@citas.demo', 'password-equivocada-1');
    assert.equal(inexistente.res.status, 401);
    assert.equal(inexistente.body.error.message, mala.body.error.message, 'mensaje genérico idéntico (no enumerar usuarios)');
  } finally {
    server.close();
  }
});

test('login rechaza usuario inactivo con el mismo mensaje genérico', async () => {
  const { server, base } = await crearBase();
  try {
    const { res, body } = await login(base, 'ina@citas.demo', PASS_ADMIN);
    assert.equal(res.status, 401);
    assert.equal(body.error.message, 'Credenciales inválidas');
  } finally {
    server.close();
  }
});

test('login con cuerpo inválido responde 400', async () => {
  const { server, base } = await crearBase();
  try {
    const { res } = await login(base, 'no-es-correo', 'x');
    assert.equal(res.status, 400);
  } finally {
    server.close();
  }
});

test('login limita intentos fallidos consecutivos (429) y se recupera tras el éxito', async () => {
  const { server, base } = await crearBase();
  try {
    for (let i = 0; i < 5; i++) {
      const { res } = await login(base, 'admin@citas.demo', 'mala');
      assert.equal(res.status, 401, `intento ${i + 1}`);
    }
    const bloqueado = await login(base, 'admin@citas.demo', PASS_ADMIN);
    assert.equal(bloqueado.res.status, 429);
    assert.equal(bloqueado.body.error.code, 'RATE_LIMITED');
    const otroUsuario = await login(base, 'soli@citas.demo', PASS_SOLI);
    assert.equal(otroUsuario.res.status, 200, 'el límite es por correo');
  } finally {
    server.close();
  }
});

// ---------- CP-BACK-04: logout + me ----------

test('GET /auth/me devuelve el usuario de la sesión o 401 sin token', async () => {
  const { server, base } = await crearBase();
  try {
    const sin = await fetch(`${base}/api/v1/auth/me`);
    assert.equal(sin.status, 401);
    const { body } = await login(base, 'soli@citas.demo', PASS_SOLI);
    const con = await fetch(`${base}/api/v1/auth/me`, { headers: { authorization: `Bearer ${body.token}` } });
    assert.equal(con.status, 200);
    const datos = await con.json();
    assert.equal(datos.correo, 'soli@citas.demo');
    assert.equal(datos.hash_contrasena, undefined);
  } finally {
    server.close();
  }
});

test('POST /auth/logout revoca la sesión (401 posterior)', async () => {
  const { server, base } = await crearBase();
  try {
    const { body } = await login(base, 'soli@citas.demo', PASS_SOLI);
    const out = await fetch(`${base}/api/v1/auth/logout`, {
      method: 'POST',
      headers: { authorization: `Bearer ${body.token}` },
    });
    assert.equal(out.status, 200);
    const me = await fetch(`${base}/api/v1/auth/me`, { headers: { authorization: `Bearer ${body.token}` } });
    assert.equal(me.status, 401);
  } finally {
    server.close();
  }
});

test('token basura responde 401 en /me', async () => {
  const { server, base } = await crearBase();
  try {
    const res = await fetch(`${base}/api/v1/auth/me`, { headers: { authorization: 'Bearer f'.repeat(32) } });
    assert.equal(res.status, 401);
  } finally {
    server.close();
  }
});

// ---------- CP-BACK-05/06/07/08: catálogo protegido ----------

test('GET listado y detalle siguen públicos (RF-027) sin token', async () => {
  const { server, base } = await crearBase();
  try {
    const lista = await fetch(`${base}/api/v1/servicios`);
    assert.equal(lista.status, 200);
    const detalle = await fetch(`${base}/api/v1/servicios/1`);
    assert.equal(detalle.status, 200);
  } finally {
    server.close();
  }
});

test('mutaciones sin token responden 401 UNAUTHORIZED', async () => {
  const { server, base } = await crearBase();
  try {
    const post = await fetch(`${base}/api/v1/servicios`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ nombre: 'X', duracion_minutos: 10 }),
    });
    assert.equal(post.status, 401);
    assert.equal((await post.json()).error.code, 'UNAUTHORIZED');
    assert.equal((await fetch(`${base}/api/v1/servicios/1`, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ nombre: 'X', duracion_minutos: 10 }) })).status, 401);
    assert.equal((await fetch(`${base}/api/v1/servicios/1`, { method: 'DELETE' })).status, 401);
  } finally {
    server.close();
  }
});

test('mutaciones con rol solicitante responden 403 FORBIDDEN (RF-003)', async () => {
  const { server, base } = await crearBase();
  try {
    const { body } = await login(base, 'soli@citas.demo', PASS_SOLI);
    const headers = { authorization: `Bearer ${body.token}`, 'content-type': 'application/json' };
    const post = await fetch(`${base}/api/v1/servicios`, {
      method: 'POST', headers, body: JSON.stringify({ nombre: 'X', duracion_minutos: 10 }),
    });
    assert.equal(post.status, 403);
    assert.equal((await post.json()).error.code, 'FORBIDDEN');
    assert.equal((await fetch(`${base}/api/v1/servicios/1`, { method: 'DELETE', headers })).status, 403);
  } finally {
    server.close();
  }
});

test('administrador puede crear, actualizar y desactivar servicios (RF-005)', async () => {
  const { server, base } = await crearBase();
  try {
    const { body } = await login(base, 'admin@citas.demo', PASS_ADMIN);
    const headers = { authorization: `Bearer ${body.token}`, 'content-type': 'application/json' };
    const creado = await fetch(`${base}/api/v1/servicios`, {
      method: 'POST', headers, body: JSON.stringify({ nombre: 'Ecografía', duracion_minutos: 40 }),
    });
    assert.equal(creado.status, 201);
    const id = (await creado.json()).id;
    const put = await fetch(`${base}/api/v1/servicios/${id}`, {
      method: 'PUT', headers, body: JSON.stringify({ nombre: 'Ecografía abdominal', duracion_minutos: 45 }),
    });
    assert.equal(put.status, 200);
    assert.equal((await put.json()).nombre, 'Ecografía abdominal');
    const del = await fetch(`${base}/api/v1/servicios/${id}`, { method: 'DELETE', headers });
    assert.equal(del.status, 200);
    assert.equal((await del.json()).estado, 'inactivo');
  } finally {
    server.close();
  }
});

