+  async findByClaves(p, s) { const f = this.filas.find((a) => a.profesional_id === p && a.servicio_id === s); return f ? { ...f } : null; }
+  async create(d) {
+    const f = { estado: 'activa', registrado_utc: ahoraUtcMysql(), baja_utc: null, duracion_especifica: null, ...d };
+    this.filas.push(f);
