+  async update(id, { nombre_completo, estado }) {
+    await this.#e.execute(
+      `UPDATE usuario SET nombre_completo = COALESCE(:n, nombre_completo), estado = COALESCE(:e, estado), actualizado_utc = :a WHERE id = :id`,
