+      .filter((c) => c.profesional_id === p && ['Confirmada', 'En atención'].includes(c.estado)
+        && t(c.inicio_utc) < t(fin) && t(c.fin_utc) > t(ini) && c.id !== excluir)
+      .map((c) => ({ id: c.id }));
