export const OFFSET_LOCAL_HORAS = -4;
const DIAS = ['dom', 'lun', 'mar', 'mie', 'jue', 'vie', 'sat'];

export function minutosDesdeMedianoche(hhmm) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm));
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}

export function hhmmDesdeMinutos(min) {
  return `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
}

export function diaSemanaLocal(fecha) {
  const [y, m, d] = String(fecha).split('-').map(Number);
  if (!y || !m || !d) return null;
  return DIAS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
}

export function aUtc(fecha, hhmm) {
  const [y, m, d] = String(fecha).split('-').map(Number);
  const min = minutosDesdeMedianoche(hhmm);
  if (!y || min === null) return null;
  return new Date(Date.UTC(y, m - 1, d, min / 60 + -OFFSET_LOCAL_HORAS, min % 60));
}

export function aLocal(dateUtc) {
  const local = new Date(dateUtc.getTime() + OFFSET_LOCAL_HORAS * 3600000);
  const fecha = local.toISOString().slice(0, 10);
  const hhmm = local.toISOString().slice(11, 16);
  const dia = DIAS[local.getUTCDay()];
  return { fecha, hora: hhmm, dia };
}

export function esFechaValida(fecha) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(fecha)) && !Number.isNaN(Date.parse(`${fecha}T00:00:00Z`));
}

export function minutosEntreUtc(a, b) {
  return (b.getTime() - a.getTime()) / 60000;
}

import { AppError } from '../http/errors.js';

export function crearUowMysql(pool) {
  return async function ejecutarTransaccion({ lock } = {}, fn) {
    const conn = await pool.getConnection();
    let bloqueado = false;
    try {
      await conn.beginTransaction();
      if (lock) {
        const [filas] = await conn.query('SELECT GET_LOCK(?, 5) AS l', [lock]);
        if (Number(filas[0].l) !== 1) {
          throw new AppError('Operación en curso para este profesional; reintente', { status: 409, code: 'CONFLICTO_CONCURRENCIA' });
        }
        bloqueado = true;
      }
      const resultado = await fn(conn);
      await conn.commit();
      return resultado;
    } catch (err) {
      try { await conn.rollback(); } catch { /* noop */ }
      throw err;
    } finally {
      if (bloqueado) {
        try { await conn.query('SELECT RELEASE_LOCK(?)', [lock]); } catch { /* noop */ }
      }
      conn.release();
    }
  };
}

export function crearUowMemoria(repositorios) {
  const colas = new Map();
  return async function ejecutarTransaccion({ lock = 'global' } = {}, fn) {
    const anterior = colas.get(lock) ?? Promise.resolve();
    let liberar;
    const turno = new Promise((r) => { liberar = r; });
    colas.set(lock, anterior.then(() => turno));
    await anterior;
    try {
      return await fn(repositorios);
    } finally {
      liberar();
    }
  };
}

import { ValidationError } from '../../../../shared/http/errors.js';
import { minutosDesdeMedianoche, esFechaValida } from '../../../../shared/time/lapaz.js';

export const DIAS = ['lun', 'mar', 'mie', 'jue', 'vie', 'sat', 'dom'];
export const TIPOS_EXCEPCION = ['ausencia', 'feriado', 'bloqueo'];

export function parseHorarioBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  if (!DIAS.includes(body.dia_semana)) throw new ValidationError("'dia_semana' debe ser lun..dom", { campo: 'dia_semana' });
  const inicio = minutosDesdeMedianoche(body.hora_inicio);
  const fin = minutosDesdeMedianoche(body.hora_fin);
  if (inicio === null) throw new ValidationError("'hora_inicio' debe ser HH:MM válido", { campo: 'hora_inicio' });
  if (fin === null) throw new ValidationError("'hora_fin' debe ser HH:MM válido", { campo: 'hora_fin' });
  if (fin <= inicio) throw new ValidationError("'hora_fin' debe ser mayor que 'hora_inicio'", { campo: 'hora_fin' });
  return { dia_semana: body.dia_semana, hora_inicio: body.hora_inicio, hora_fin: body.hora_fin };
}

export function parseExcepcionBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  if (!esFechaValida(body.fecha)) throw new ValidationError("'fecha' debe ser YYYY-MM-DD válido", { campo: 'fecha' });
  if (!TIPOS_EXCEPCION.includes(body.tipo)) throw new ValidationError("'tipo' debe ser ausencia, feriado o bloqueo", { campo: 'tipo' });
  const hi = body.hora_inicio === undefined || body.hora_inicio === null ? null : minutosDesdeMedianoche(body.hora_inicio);
  const hf = body.hora_fin === undefined || body.hora_fin === null ? null : minutosDesdeMedianoche(body.hora_fin);
  if ((hi === null) !== (hf === null)) throw new ValidationError("'hora_inicio' y 'hora_fin' deben ir juntos o ausentes", { campo: 'hora_inicio' });
  if (hi !== null) {
    if (hi === null || hf === null || hf <= hi) throw new ValidationError("'hora_fin' debe ser mayor que 'hora_inicio'", { campo: 'hora_fin' });
  }
  if (body.motivo !== undefined && body.motivo !== null && (typeof body.motivo !== 'string' || body.motivo.length > 200)) {
    throw new ValidationError("'motivo' debe ser texto de máximo 200 caracteres", { campo: 'motivo' });
  }
  return { fecha: body.fecha, tipo: body.tipo, hora_inicio: body.hora_inicio ?? null, hora_fin: body.hora_fin ?? null, motivo: body.motivo ?? null };
}

import { minutosDesdeMedianoche, hhmmDesdeMinutos, diaSemanaLocal, aUtc, aLocal } from '../../../../shared/time/lapaz.js';

const PASO_MIN = 15;
const ESTADOS_QUE_OCUPAN = ['Confirmada', 'En atención'];

function solapa(aInicio, aFin, bInicio, bFin) {
  return aInicio < bFin && bInicio < aFin;
}

function excepcionAfecta(excepcion, dia, inicioMin, finMin) {
  if (excepcion.fecha !== dia) return false;
  if (excepcion.hora_inicio === null) return true;
  return solapa(inicioMin, finMin, minutosDesdeMedianoche(excepcion.hora_inicio), minutosDesdeMedianoche(excepcion.hora_fin));
}

export function intervalosDisponibles({ horarios, excepciones, citas, fecha, duracionMin }) {
  const dia = diaSemanaLocal(fecha);
  const dur = Number(duracionMin);
  const candidatos = [];
  for (const h of horarios) {
    if (h.dia_semana !== dia) continue;
    const inicio = minutosDesdeMedianoche(h.hora_inicio);
    const fin = minutosDesdeMedianoche(h.hora_fin);
    for (let s = inicio; s + dur <= fin; s += PASO_MIN) candidatos.push(s);
  }
  const citasLocales = citas
    .filter((c) => ESTADOS_QUE_OCUPAN.includes(c.estado))
    .map((c) => ({ ini: aLocal(new Date(c.inicio_utc)), fin: aLocal(new Date(c.fin_utc)) }));
  return candidatos.filter((iniMin) => {
    const finMin = iniMin + dur;
    if (excepciones.some((e) => excepcionAfecta(e, dia, iniMin, finMin))) return false;
    return !citasLocales.some((c) => {
      const cIni = minutosDesdeMedianoche(c.ini.hora);
      const cFin = minutosDesdeMedianoche(c.fin.hora);
      if (c.ini.fecha !== fecha) return false;
      return solapa(iniMin, finMin, cIni, cFin);
    });
  }).map((m) => hhmmDesdeMinutos(m));
}

export function slotDisponible(params, hhmm) {
  return intervalosDisponibles(params).includes(hhmm);
}

export function aUtcSlot(fecha, hhmm) {
  return aUtc(fecha, hhmm);
}

import { ValidationError } from '../../../../shared/http/errors.js';
import { esFechaValida, minutosDesdeMedianoche } from '../../../../shared/time/lapaz.js';

export const ESTADOS = ['Confirmada', 'En atención', 'Atendida', 'Cancelada', 'No asistida'];
export const TRANSICIONES = {
  'Confirmada': ['En atención', 'Cancelada', 'No asistida'],
  'En atención': ['Atendida'],
  'Atendida': [],
  'Cancelada': [],
  'No asistida': [],
};
const FINALES = ['Atendida', 'Cancelada', 'No asistida'];

export function esEstadoFinal(estado) {
  return FINALES.includes(estado);
}

export function transicionPermitida(desde, hacia) {
  return (TRANSICIONES[desde] ?? []).includes(hacia);
}

function idPositivo(valor, campo) {
  const n = Number(valor);
  if (!Number.isInteger(n) || n <= 0) throw new ValidationError(`'${campo}' debe ser un entero positivo`, { campo });
  return n;
}

export function parseReservaBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  if (!esFechaValida(body.fecha)) throw new ValidationError("'fecha' debe ser YYYY-MM-DD válido", { campo: 'fecha' });
  if (minutosDesdeMedianoche(body.hora_inicio) === null) throw new ValidationError("'hora_inicio' debe ser HH:MM válido", { campo: 'hora_inicio' });
  return {
    servicio_id: idPositivo(body.servicio_id, 'servicio_id'),
    profesional_id: idPositivo(body.profesional_id, 'profesional_id'),
    fecha: body.fecha,
    hora_inicio: body.hora_inicio,
  };
}

export function parseReprogramarBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  if (!esFechaValida(body.fecha)) throw new ValidationError("'fecha' debe ser YYYY-MM-DD válido", { campo: 'fecha' });
  if (minutosDesdeMedianoche(body.hora_inicio) === null) throw new ValidationError("'hora_inicio' debe ser HH:MM válido", { campo: 'hora_inicio' });
  return { fecha: body.fecha, hora_inicio: body.hora_inicio, justificacion: validarJustificacionOpcional(body.justificacion) };
}

export function parseCancelarBody(body) {
  if (body !== undefined && body !== null && (typeof body !== 'object' || Array.isArray(body))) {
    throw new ValidationError('El cuerpo debe ser un objeto JSON');
  }
  return { justificacion: validarJustificacionOpcional(body?.justificacion) };
}

function validarJustificacionOpcional(valor) {
  if (valor === undefined || valor === null || valor === '') return null;
  if (typeof valor !== 'string' || valor.length > 500) {
    throw new ValidationError("'justificacion' debe ser texto de máximo 500 caracteres", { campo: 'justificacion' });
  }
  return valor;
}

export function justificacionRequerida(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  const justificacion = validarJustificacionOpcional(body.justificacion);
  if (!justificacion) throw new ValidationError("'justificacion' es obligatoria para cambios fuera de plazo", { campo: 'justificacion' });
  return justificacion;
}

export function puedeModificarCita(rol, usuarioId, cita) {
  if (rol === 'administrador') return true;
  if (rol === 'solicitante') return cita.solicitante_id === usuarioId;
  if (rol === 'profesional') return cita.profesional_id === usuarioId;
  return false;
}

export function aSeguroCita(row) {
  return {
    id: row.id,
    solicitante_id: row.solicitante_id,
    profesional_id: row.profesional_id,
    servicio_id: row.servicio_id,
    inicio_utc: row.inicio_utc,
