import { ValidationError } from '../../../../shared/http/errors.js';
import { passwordSeguraValida } from '../../../../shared/security/passwords.js';

const ROLES = ['solicitante', 'profesional', 'administrador'];
const ESTADOS = ['activo', 'inactivo'];

function cuerpo(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  return body;
}

function validarCorreo(correo) {
  const c = typeof correo === 'string' ? correo.trim().toLowerCase() : '';
  if (!c || !c.includes('@') || c.length > 254) throw new ValidationError("'correo' debe ser un correo electrónico válido", { campo: 'correo' });
  return c;
}

function validarNombre(nombre) {
  const n = typeof nombre === 'string' ? nombre.trim() : '';
  if (!n || n.length > 150) throw new ValidationError("'nombre_completo' debe ser un texto de 1 a 150 caracteres", { campo: 'nombre_completo' });
  return n;
}

function validarPassword(p) {
  if (!passwordSeguraValida(p)) throw new ValidationError("'contrasena' debe tener entre 12 y 200 caracteres (RNF-029)", { campo: 'contrasena' });
  return p;
}

export function parseCrearUsuarioBody(body) {
  const b = cuerpo(body);
  if (!ROLES.includes(b.rol)) throw new ValidationError("'rol' debe ser solicitante, profesional o administrador", { campo: 'rol' });
  return {
    nombre_completo: validarNombre(b.nombre_completo),
    correo: validarCorreo(b.correo),
    contrasena: validarPassword(b.contrasena),
    rol: b.rol,
  };
}

export function parseActualizarUsuarioBody(body) {
  const b = cuerpo(body);
  if (b.nombre_completo === undefined && b.estado === undefined) throw new ValidationError('Debe indicar nombre_completo y/o estado');
  if (b.estado !== undefined && !ESTADOS.includes(b.estado)) throw new ValidationError("'estado' debe ser activo o inactivo", { campo: 'estado' });
  return { nombre_completo: b.nombre_completo !== undefined ? validarNombre(b.nombre_completo) : undefined, estado: b.estado };
}

export function parseCrearProfesionalBody(body) {
  const b = cuerpo(body);
  if (b.datos_exhibicion !== undefined && b.datos_exhibicion !== null && (typeof b.datos_exhibicion !== 'string' || b.datos_exhibicion.length > 255)) {
    throw new ValidationError("'datos_exhibicion' debe ser texto de máximo 255 caracteres", { campo: 'datos_exhibicion' });
  }
  return {
    nombre_completo: validarNombre(b.nombre_completo),
    correo: validarCorreo(b.correo),
    contrasena: validarPassword(b.contrasena),
    datos_exhibicion: b.datos_exhibicion ?? null,
  };
}

export function parseActualizarProfesionalBody(body) {
  const b = cuerpo(body);
  if (b.datos_exhibicion === undefined && b.estado === undefined) throw new ValidationError('Debe indicar datos_exhibicion y/o estado');
  if (b.estado !== undefined && !ESTADOS.includes(b.estado)) throw new ValidationError("'estado' debe ser activo o inactivo", { campo: 'estado' });
  if (b.datos_exhibicion !== undefined && b.datos_exhibicion !== null && (typeof b.datos_exhibicion !== 'string' || b.datos_exhibicion.length > 255)) {
    throw new ValidationError("'datos_exhibicion' debe ser texto de máximo 255 caracteres", { campo: 'datos_exhibicion' });
  }
  return { datos_exhibicion: b.datos_exhibicion, estado: b.estado };
}

import { AppError, ValidationError, NotFoundError } from '../../../../shared/http/errors.js';
import { hashPassword } from '../../../../shared/security/passwords.js';
import { toUsuarioSeguro } from '../domain/usuario.js';

export function crearCasosAdminUsuarios({ ejecutarTransaccion }) {
  return {
    listarUsuarios: ({ rol, estado } = {}) => ejecutarTransaccion({}, (r) => r.usuarioAdmin.findAll({ rol, estado })),

    obtenerUsuario: ({ id }) => ejecutarTransaccion({}, async (r) => {
      const u = await r.usuarioAdmin.findById(id);
      if (!u) throw new NotFoundError('Usuario no encontrado');
      return toUsuarioSeguro({ ...u, estado: u.estado });
    }),

    crearUsuario: ({ datos }) => ejecutarTransaccion({}, async (r) => {
      const duplicado = await r.usuarioAdmin.findByCorreo(datos.correo);
      if (duplicado) throw new AppError('Ya existe un usuario con ese correo', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      const u = await r.usuarioAdmin.create({
        nombre_completo: datos.nombre_completo,
        correo: datos.correo,
        hash_contrasena: hashPassword(datos.contrasena),
        rol: datos.rol,
      });
      return toUsuarioSeguro(u);
    }),

    actualizarUsuario: ({ id, datos }) => ejecutarTransaccion({}, async (r) => {
      const u = await r.usuarioAdmin.update(id, datos);
      if (!u) throw new NotFoundError('Usuario no encontrado');
      return toUsuarioSeguro(u);
    }),

    listarProfesionales: ({ estado } = {}) => ejecutarTransaccion({}, (r) => r.profesionales.findAll({ estado })),

    crearProfesional: ({ datos }) => ejecutarTransaccion({ lock: 'usuarios-creacion' }, async (r) => {
      const duplicado = await r.usuarioAdmin.findByCorreo(datos.correo);
      if (duplicado) throw new AppError('Ya existe un usuario con ese correo', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      const u = await r.usuarioAdmin.create({
        nombre_completo: datos.nombre_completo,
        correo: datos.correo,
        hash_contrasena: hashPassword(datos.contrasena),
        rol: 'profesional',
      });
      const p = await r.profesionales.create({ usuario_id: u.id, datos_exhibicion: datos.datos_exhibicion });
      return { ...p, nombre_completo: u.nombre_completo, correo: u.correo };
    }),

    actualizarProfesional: ({ id, datos }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.update(id, datos);
      if (!p) throw new NotFoundError('Profesional no encontrado');
      return p;
    }),

    obtenerProfesional: ({ id }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(id);
      if (!p) throw new NotFoundError('Profesional no encontrado');
      return p;
    }),
  };
}

export function parseCrearAsociacionBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  const servicioId = Number(body.servicio_id);
  if (!Number.isInteger(servicioId) || servicioId <= 0) throw new ValidationError("'servicio_id' debe ser un entero positivo", { campo: 'servicio_id' });
  let duracion = null;
  if (body.duracion_especifica !== undefined && body.duracion_especifica !== null) {
    duracion = Number(body.duracion_especifica);
    if (!Number.isInteger(duracion) || duracion < 1 || duracion > 1440) {
      throw new ValidationError("'duracion_especifica' debe ser un entero entre 1 y 1440", { campo: 'duracion_especifica' });
    }
  }
  return { servicioId, duracion };
}

export function parseActualizarAsociacionBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  if (body.duracion_especifica === undefined && body.estado === undefined) throw new ValidationError('Debe indicar duracion_especifica y/o estado');
  if (body.estado !== undefined && !['activa', 'inactiva'].includes(body.estado)) {
    throw new ValidationError("'estado' debe ser activa o inactiva", { campo: 'estado' });
  }
  let duracion;
  if (body.duracion_especifica !== undefined && body.duracion_especifica !== null) {
    duracion = Number(body.duracion_especifica);
    if (!Number.isInteger(duracion) || duracion < 1 || duracion > 1440) {
      throw new ValidationError("'duracion_especifica' debe ser un entero entre 1 y 1440", { campo: 'duracion_especifica' });
    }
  }
  return { duracion, estado: body.estado };
}

export function crearCasosAsociaciones({ ejecutarTransaccion }) {
  return {
    listarAsociaciones: ({ profesionalId }) => ejecutarTransaccion({}, (r) => r.asociaciones.findAllByProfesional(profesionalId)),

    crearAsociacion: ({ profesionalId, datos }) => ejecutarTransaccion({}, async (r) => {
      const profesional = await r.profesionales.findById(profesionalId);
      if (!profesional || profesional.estado !== 'activo') throw new NotFoundError('Profesional inexistente o inactivo');
      const servicio = await r.servicios.findById(datos.servicioId);
      if (!servicio || servicio.estado !== 'activo') throw new NotFoundError('Servicio inexistente o inactivo');
      const previa = await r.asociaciones.findByClaves(profesionalId, datos.servicioId);
      if (previa) throw new AppError('La asociación ya existe (use PUT para modificarla)', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      const a = await r.asociaciones.create({ profesional_id: profesionalId, servicio_id: datos.servicioId, duracion_especifica: datos.duracion });
      return a;
    }),

    actualizarAsociacion: ({ profesionalId, servicioId, datos }) => ejecutarTransaccion({}, async (r) => {
      const previa = await r.asociaciones.findByClaves(profesionalId, servicioId);
      if (!previa) throw new NotFoundError('Asociación no encontrada');
      return r.asociaciones.update(profesionalId, servicioId, { duracion_especifica: datos.duracion, estado: datos.estado });
    }),
  };
}

import { AppError, NotFoundError } from '../../../../shared/http/errors.js';
import { parseHorarioBody, parseExcepcionBody } from '../domain/horario.js';
import { intervalosDisponibles } from '../domain/disponibilidad.js';
import { minutosDesdeMedianoche } from '../../../../shared/time/lapaz.js';

function solapes(aIni, aFin, bIni, bFin) {
  return aIni < bFin && bIni < aFin;
}

export function crearCasosAgenda({ ejecutarTransaccion }) {
  return {
    listarHorarios: ({ profesionalId }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(profesionalId);
      if (!p) throw new NotFoundError('Profesional no encontrado');
      return r.horarios.findAllByProfesional(profesionalId);
    }),

    agregarHorario: ({ profesionalId, body }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(profesionalId);
      if (!p || p.estado !== 'activo') throw new NotFoundError('Profesional inexistente o inactivo');
      const datos = parseHorarioBody(body);
      const ini = minutosDesdeMedianoche(datos.hora_inicio);
      const fin = minutosDesdeMedianoche(datos.hora_fin);
      const existentes = await r.horarios.findAllByProfesional(profesionalId);
      const choque = existentes.some((h) => h.dia_semana === datos.dia_semana
        && solapes(ini, fin, minutosDesdeMedianoche(h.hora_inicio), minutosDesdeMedianoche(h.hora_fin)));
      if (choque) throw new AppError('El horario se solapa con uno existente', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      return r.horarios.create({ profesional_id: profesionalId, ...datos });
    }),

    quitarHorario: ({ horarioId }) => ejecutarTransaccion({}, async (r) => {
      const h = await r.horarios.findById(horarioId);
      if (!h) throw new NotFoundError('Horario no encontrado');
      await r.horarios.delete(horarioId);
      return { eliminado: true };
    }),

    listarExcepciones: ({ profesionalId, fecha }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(profesionalId);
      if (!p) throw new NotFoundError('Profesional no encontrado');
      return r.excepciones.findAllByProfesional(profesionalId, fecha ?? null);
    }),

    agregarExcepcion: ({ profesionalId, body }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(profesionalId);
      if (!p || p.estado !== 'activo') throw new NotFoundError('Profesional inexistente o inactivo');
      const datos = parseExcepcionBody(body);
      return r.excepciones.create({ profesional_id: profesionalId, ...datos });
    }),

    quitarExcepcion: ({ excepcionId }) => ejecutarTransaccion({}, async (r) => {
      const e = await r.excepciones.findById(excepcionId);
      if (!e) throw new NotFoundError('Excepción no encontrada');
      await r.excepciones.delete(excepcionId);
      return { eliminado: true };
    }),

    consultarDisponibilidad: ({ profesionalId, servicioId, fecha }) => ejecutarTransaccion({}, async (r) => {
      const p = await r.profesionales.findById(profesionalId);
      if (!p || p.estado !== 'activo') throw new NotFoundError('Profesional inexistente o inactivo');
      const s = await r.servicios.findById(servicioId);
      if (!s || s.estado !== 'activo') throw new NotFoundError('Servicio inexistente o inactivo');
      const a = await r.asociaciones.findByClaves(profesionalId, servicioId);
      if (!a || a.estado !== 'activa') {
        throw new AppError('El profesional no tiene una asociación activa con el servicio', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      }
      const duracion = a.duracion_especifica ?? s.duracion_minutos;
      const [horarios, excepciones, citas] = await Promise.all([
        r.horarios.findAllByProfesional(profesionalId),
        r.excepciones.findAllByProfesional(profesionalId, fecha),
        r.citas.findAll({ profesionalId, fecha }),
      ]);
      const intervalos = intervalosDisponibles({ horarios, excepciones, citas, fecha, duracionMin: duracion });
      return { profesional_id: profesionalId, servicio_id: servicioId, fecha, duracion_efectiva_min: duracion, intervalos };
    }),
  };
}

import { ValidationError } from '../../../../shared/http/errors.js';

export const CLAVES_CONOCIDAS = ['anticipacion_reservar', 'anticipacion_reprogramar', 'anticipacion_cancelar'];
export const MINUTOS_REPROGRAMAR_CANCELAR_APROBADOS = 120;

export async function valorMinutosParametro(parametros, clave, predeterminado = null) {
  const p = await parametros.findByClave(clave);
  if (!p) return predeterminado;
  const n = Number(p.valor);
  return Number.isInteger(n) && n >= 0 ? n : predeterminado;
}

export function parseParametroBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('El cuerpo debe ser un objeto JSON');
  const clave = typeof body.clave === 'string' ? body.clave.trim() : '';
  if (!CLAVES_CONOCIDAS.includes(clave)) {
    throw new ValidationError(`'clave' debe ser una de: ${CLAVES_CONOCIDAS.join(', ')}`, { campo: 'clave' });
  }
  const n = Number(body.valor);
  if (!Number.isInteger(n) || n < 0 || n > 10080) {
    throw new ValidationError("'valor' debe ser un entero de minutos entre 0 y 10080", { campo: 'valor' });
  }
  if (body.descripcion !== undefined && body.descripcion !== null && (typeof body.descripcion !== 'string' || body.descripcion.length > 200)) {
    throw new ValidationError("'descripcion' debe ser texto de máximo 200 caracteres", { campo: 'descripcion' });
  }
  return { clave, valor: String(n), descripcion: body.descripcion ?? null };
}

export function crearCasosParametros({ ejecutarTransaccion, reloj = () => new Date() }) {
  return {
    listarParametros: () => ejecutarTransaccion({}, async (r) => {
      const filas = await r.parametros.findAll();
      const porClave = new Map(filas.map((f) => [f.clave, f]));
      return CLAVES_CONOCIDAS.map((clave) => ({
        clave,
        valor: porClave.get(clave)?.valor ?? null,
        descripcion: porClave.get(clave)?.descripcion ?? null,
        configurado: porClave.has(clave),
      }));
    }),

    configurarParametro: ({ clave, datos, usuarioId }) => ejecutarTransaccion({}, (r) => r.parametros.upsert({
      clave: clave ?? datos.clave,
      valor: datos.valor,
      descripcion: datos.descripcion,
      modificadoPor: usuarioId,
      modificadoUtc: (() => { const iso = reloj().toISOString(); return `${iso.slice(0, 19).replace('T', ' ')}${iso.slice(19, 23)}`; })(),
    })),
  };
}

