**reprogramar:**

```js
export function crearReprogramarCita({ ejecutarTransaccion, reloj = () => new Date() }) {
  return async function reprogramarCita({ citaId, actor, datos, idempotenciaKey }) {
    const clave = validarClaveIdempotencia(idempotenciaKey);
    // primero leer cita para conocer profesional (para el lock)
    const preliminar = await ejecutarTransaccion({}, (repos) => repos.citas.findById(citaId));
    if (!preliminar) throw new NotFoundError('Cita no encontrada');
    return ejecutarTransaccion({ lock: `cita-prof-${preliminar.profesional_id}` }, async (repos) => {
      const previa = await repos.claves.findByClave(clave);
      if (previa) { ...reprogramacion check → return cita actual {replique:true} }
      const ahora = reloj();
      const cita = await repos.citas.findById(citaId);
      if (!cita) throw new NotFoundError('Cita no encontrada');
      if (!puedeModificarCita(actor.rol, actor.id, cita)) throw new AppError('No autorizado para modificar esta cita', { status: 403, code: 'FORBIDDEN' });
      if (cita.estado !== 'Confirmada') throw new AppError('Solo citas Confirmada pueden reprogramarse (RN-08/RN-13)', { status: 409, code: 'ESTADO_NO_MODIFICABLE' });
      const minReprog = (await valorMinutosParametro(repos.parametros, 'anticipacion_reprogramar', MINUTOS_REPROGRAMAR_CANCELAR_APROBADOS));
      const inicioActual = new Date(cita.inicio_utc);
      const fueraPlazo = minutosEntreUtc(ahora, inicioActual) < minReprog;
      const esGestor = actor.rol === 'administrador' || actor.rol === 'profesional';
      let justificacion = datos.justificacion;
      if (fueraPlazo) {
        if (!esGestor) throw new AppError(`Reprogramación fuera del plazo mínimo (${minReprog} minutos); contacte a la institución`, { status: 409, code: 'FUERA_DE_PLAZO' });
        if (!justificacion) throw new ValidationError("'justificacion' es obligatoria para reprogramar fuera del plazo mínimo", { campo: 'justificacion' });
      }
      // asociación sigue activa (RN-16/RF-017)
      const asociacion = await repos.asociaciones.findByClaves(cita.profesional_id, cita.servicio_id);
      if (!asociacion || asociacion.estado !== 'activa') throw new AppError('La asociación profesional-servicio ya no está activa', { status: 409, code: 'CONFLICTO_ASOCIACION' });
      // nuevo slot
      const duracion = cita.duracion_efectiva_min;
      const [horarios, excepciones] = await Promise.all([...]);
      if (!slotDisponible({horarios, excepciones, citas: [], fecha: datos.fecha, duracionMin: duracion}, datos.hora_inicio)) throw INTERVALO_NO_DISPONIBLE;
      const inicioNuevo = aUtc(datos.fecha, datos.hora_inicio);
      const finNuevo = new Date(inicioNuevo.getTime() + duracion * 60000);
      if (inicioNuevo.getTime() === inicioActual.getTime()) throw new ValidationError('El nuevo horario debe ser distinto al actual', {campo: 'hora_inicio'});
      const solapadas = await repos.citas.findSolapadas(cita.profesional_id, inicioNuevo, finNuevo, citaId);
      if (solapadas.length) throw INTERVALO_OCUPADO;
      const citaActualizada = await repos.citas.update(citaId, {
        inicio_utc: inicioNuevo, fin_utc: finNuevo, estado: 'Confirmada', justificacion_cambio: justificacion, ahora,
      });
      await repos.historial.insert({ cita_id: citaId, usuario_id: actor.id, tipo_cambio: 'reprogramacion', estado_anterior: 'Confirmada', estado_nuevo: 'Confirmada', fecha_anterior_utc: cita.inicio_utc, fecha_nueva_utc: inicioNuevo, ahora, justificacion });
      await repos.auditoria.insert({ usuario_id: actor.id, cita_id: citaId, tipo_operacion: 'reprogramacion', fecha_hora_utc: ahora, resultado: 'exito', contexto: JSON.stringify({ idempotencia: clave }) });
      await repos.outbox.insert({ correlacion_id: ..., tipo_evento: 'cita_reprogramada', cita_id: citaId, carga: JSON.stringify({ destinatario_id: cita.solicitante_id, instantanea_datos: instantaneaCita(citaActualizada) }), ahora });
      await repos.claves.create({ clave, usuarioId: actor.id, tipoOperacion: 'reprogramacion', solicitud: JSON.stringify(datos), resultado: JSON.stringify(aSeguroCita(citaActualizada)), creadaUtc: ahora, caducaUtc: new Date(ahora.getTime() + TTL) });
      return { replique: false, cita: aSeguroCita(citaActualizada) };
    });
  };
}
