export function crearProcesarOutbox({ outboxRepository, notificacionRepository, reloj = () => new Date() }) {
  return async function procesarOutbox() {
    const pendientes = await outboxRepository.findPendientes(50);
    let procesados = 0;
    for (const evento of pendientes) {
      try {
        const carga = JSON.parse(evento.carga);
        await notificacionRepository.insert({
          destinatario_id: carga.destinatario_id,
          cita_id: evento.cita_id,
          evento: carga.evento,
          instantanea_datos: carga.instantanea_datos,
          ahora: ahoraUtcMysql(reloj()),
        });
        await outboxRepository.markProcesado(evento.id, ahoraUtcMysql(reloj()));
        procesados += 1;
      } catch (err) {
        console.error('[notificaciones] fallo al procesar outbox id=', evento.id, err.message);
        try { await outboxRepository.marcarFallo(evento.id); } catch { /* noop */ }
      }
    }
    return { procesados, pendientes: pendientes.length - procesados };
  };
}

function instantaneaParseada(fila) {
