export function crearObtenerSesion({ usuarioRepository }) {
  return async function obtenerSesion({ usuarioId }) {
    const fila = await usuarioRepository.findById(usuarioId);
    if (!fila || fila.estado !== 'activo') return null;
    return toUsuarioSeguro(fila);
  };
}

export function parseRegistroBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new ValidationError('El cuerpo debe ser un objeto JSON');
  }
  if (body.rol !== undefined) {
    throw new ValidationError('En el registro público el rol siempre es solicitante', { campo: 'rol' });
  }
  const nombre = typeof body.nombre_completo === 'string' ? body.nombre_completo.trim() : '';
  if (!nombre || nombre.length > 150) {
    throw new ValidationError("'nombre_completo' debe ser un texto de 1 a 150 caracteres", { campo: 'nombre_completo' });
  }
  const correo = typeof body.correo === 'string' ? body.correo.trim().toLowerCase() : '';
  if (!correo || !correo.includes('@') || correo.length > 254) {
    throw new ValidationError("'correo' debe ser un correo electrónico válido", { campo: 'correo' });
  }
  if (!passwordSeguraValida(body.contrasena)) {
    throw new ValidationError("'contrasena' debe tener entre 12 y 200 caracteres (RNF-029)", { campo: 'contrasena' });
  }
  return { nombre_completo: nombre, correo, contrasena: body.contrasena };
}

export function crearRegistro({ ejecutarTransaccion }) {
  return async function registro({ datos }) {
    return ejecutarTransaccion({}, async (repos) => {
      const duplicado = await repos.usuarioAdmin.findByCorreo(datos.correo);
      if (duplicado) {
        throw new AppError('No fue posible completar el registro con esos datos', { status: 409, code: 'CONFLICTO_NEGOCIO' });
      }
      const usuario = await repos.usuarioAdmin.create({
        nombre_completo: datos.nombre_completo,
        correo: datos.correo,
        hash_contrasena: hashPassword(datos.contrasena),
        rol: 'solicitante',
        estado: 'activo',
      });
      return toUsuarioSeguro(usuario);
    });
  };
}

