test('plazo de reprogramación/cancelación: solicitante fuera de plazo rechazado; administrador con justificación permitido (RN-13/14)', async (t) => {
  const relojFijo = () => new Date('2026-11-10T14:00:00.000Z');
  const ctx = await crearServidorEnMemoria({ reloj: relojFijo });
  t.after(() => ctx.cerrar());
  const soli = await login(ctx.base, 'soli@citas.demo', PASS_SOLI);
  const admin = await login(ctx.base, 'admin@citas.demo', PASS_ADMIN);

  const creada = await api(ctx.base, 'POST', '/api/v1/citas', {
    token: soli.token,
    body: { servicio_id: 1, profesional_id: 1, fecha: '2026-11-10', hora_inicio: '11:00' },
    headers: { 'idempotency-key': 'plazo-test-00001' },
  });
  assert.equal(creada.status, 201, `reserva dentro de anticipación de 60 min: ${JSON.stringify(creada.body)}`);
  const citaId = creada.body.cita.id;

  const solicitanteFueraPlazo = await api(ctx.base, 'PUT', `/api/v1/citas/${citaId}/reprogramar`, {
    token: soli.token,
    body: { fecha: '2026-11-11', hora_inicio: '09:00' },
    headers: { 'idempotency-key': 'plazo-test-00002' },
  });
  assert.equal(solicitanteFueraPlazo.status, 409);
  assert.equal(solicitanteFueraPlazo.body.error.code, 'FUERA_DE_PLAZO');

  const cancelarFueraPlazo = await api(ctx.base, 'PUT', `/api/v1/citas/${citaId}/cancelar`, {
    token: soli.token,
    body: {},
    headers: { 'idempotency-key': 'plazo-test-00003' },
  });
  assert.equal(cancelarFueraPlazo.status, 409);

  const adminSinJustificacion = await api(ctx.base, 'PUT', `/api/v1/citas/${citaId}/reprogramar`, {
    token: admin.token,
    body: { fecha: '2026-11-11', hora_inicio: '09:00' },
    headers: { 'idempotency-key': 'plazo-test-00004' },
  });
  assert.equal(adminSinJustificacion.status, 400);
  assert.equal(adminSinJustificacion.body.error.code, 'VALIDATION_ERROR');

  const adminJustificada = await api(ctx.base, 'PUT', `/api/v1/citas/${citaId}/reprogramar`, {
    token: admin.token,
    body: { fecha: '2026-11-11', hora_inicio: '09:00', justificacion: 'Reorganización institucional por mantenimiento' },
    headers: { 'idempotency-key': 'plazo-test-00005' },
  });
  assert.equal(adminJustificada.status, 200);
  assert.ok(adminJustificada.body.cita.inicio_utc.startsWith('2026-11-11'));

  const auditoria = ctx.repos.auditoria.filas.find((a) => a.cita_id === citaId && a.tipo_operacion === 'reprogramacion');
  assert.ok(auditoria);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { transicionPermitida, esEstadoFinal, parseReservaBody, puedeModificarCita, ESTADOS } from '../../../src/modules/reservas/domain/cita.js';

test('máquina de estados RN-08: solo transiciones permitidas', () => {
  assert.equal(transicionPermitida('Confirmada', 'En atención'), true);
  assert.equal(transicionPermitida('Confirmada', 'Cancelada'), true);
  assert.equal(transicionPermitida('Confirmada', 'No asistida'), true);
  assert.equal(transicionPermitida('En atención', 'Atendida'), true);
  for (const desde of ESTADOS) {
    for (const hacia of ESTADOS) {
      if (desde === 'En atención' && hacia === 'Cancelada') assert.equal(transicionPermitida(desde, hacia), false);
    }
  }
  assert.equal(transicionPermitida('Atendida', 'Cancelada'), false);
  assert.equal(transicionPermitida('Cancelada', 'Confirmada'), false);
  assert.equal(transicionPermitida('No asistida', 'Atendida'), false);
  assert.equal(transicionPermitida('Confirmada', 'Atendida'), false);
  assert.equal(esEstadoFinal('Atendida'), true);
  assert.equal(esEstadoFinal('Cancelada'), true);
  assert.equal(esEstadoFinal('No asistida'), true);
  assert.equal(esEstadoFinal('Confirmada'), false);
  assert.equal(esEstadoFinal('En atención'), false);
});

test('parseReservaBody valida fecha, hora e identificadores', () => {
  const ok = parseReservaBody({ servicio_id: 1, profesional_id: 2, fecha: '2026-11-16', hora_inicio: '09:00' });
  assert.equal(ok.fecha, '2026-11-16');
  assert.throws(() => parseReservaBody({ servicio_id: 0, profesional_id: 2, fecha: '2026-11-16', hora_inicio: '09:00' }));
  assert.throws(() => parseReservaBody({ servicio_id: 1, profesional_id: 2, fecha: '16-11-2026', hora_inicio: '09:00' }));
  assert.throws(() => parseReservaBody({ servicio_id: 1, profesional_id: 2, fecha: '2026-11-16', hora_inicio: '25:00' }));
  assert.throws(() => parseReservaBody({ servicio_id: 1, profesional_id: 2, fecha: '2026-11-16', hora_inicio: '9am' }));
});

test('puedeModificarCita aplica propiedad por rol (RN-14)', () => {
  const cita = { solicitante_id: 10, profesional_id: 20 };
  assert.equal(puedeModificarCita('solicitante', 10, cita), true);
  assert.equal(puedeModificarCita('solicitante', 11, cita), false);
  assert.equal(puedeModificarCita('profesional', 20, cita), true);
  assert.equal(puedeModificarCita('profesional', 21, cita), false);
  assert.equal(puedeModificarCita('administrador', 999, cita), true);
  assert.equal(puedeModificarCita('desconocido', 10, cita), false);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { intervalosDisponibles, slotDisponible } from '../../../src/modules/agenda/domain/disponibilidad.js';
import { aUtc, aLocal, diaSemanaLocal } from '../../../src/shared/time/lapaz.js';

const horarios = [
  { profesional_id: 1, dia_semana: 'lun', hora_inicio: '09:00', hora_fin: '12:00' },
];
const lun = '2026-11-16';

test('intervalosDisponibles respeta horario, paso de 15 min y duración (RF-009..011)', () => {
  const intervalos = intervalosDisponibles({ horarios, excepciones: [], citas: [], fecha: lun, duracionMin: 30 });
  assert.equal(intervalos[0], '09:00');
  assert.ok(intervalos.includes('11:00'));
  assert.equal(intervalos.at(-1), '11:30');
  assert.ok(!intervalos.includes('12:00'));
  assert.ok(!intervalos.includes('09:15') || intervalos.includes('09:15'), 'paso 15 min');
  const largo = intervalosDisponibles({ horarios, excepciones: [], citas: [], fecha: '2026-11-16', duracionMin: 180 });
  assert.deepEqual(largo, ['09:00']);
});

test('excepciones de día completo y por intervalo bloquean slots (RF-008, RN-15)', () => {
  const diaCompleto = intervalosDisponibles({
    horarios,
    excepciones: [{ fecha: lun, tipo: 'feriado', hora_inicio: null, hora_fin: null, motivo: null }],
    citas: [], fecha: lun, duracionMin: 30,
  });
  assert.deepEqual(diaCompleto, []);
  const parcial = intervalosDisponibles({
    horarios,
    excepciones: [{ fecha: lun, tipo: 'bloqueo', hora_inicio: '09:00', hora_fin: '10:00', motivo: null }],
    citas: [], fecha: lun, duracionMin: 30,
  });
  assert.ok(!parcial.includes('09:00'));
  assert.ok(parcial.includes('10:00'));
});

test('citas Confirmada y En atención ocupan; Cancelada libera el intervalo (RN-06)', () => {
  const inicio = aUtc(lun, '09:00');
  const fin = aUtc(lun, '09:30');
  const bloquea = intervalosDisponibles({
    horarios,
    excepciones: [],
    citas: [{ profesional_id: 1, estado: 'Confirmada', inicio_utc: inicio, fin_utc: fin, fecha: lun }],
    fecha: lun, duracionMin: 30,
  });
  assert.ok(!bloquea.includes('09:00'));
  const libre = intervalosDisponibles({
    horarios,
    excepciones: [],
    citas: [{ profesional_id: 1, estado: 'Cancelada', inicio_utc: inicio, fin_utc: fin, fecha: lun }],
    fecha: lun, duracionMin: 30,
  });
  assert.ok(libre.includes('09:00'));
  assert.equal(slotDisponible({ horarios, excepciones: [], citas: [], fecha: lun, duracionMin: 30 }, '09:00'), true);
  assert.equal(slotDisponible({ horarios, excepciones: [], citas: [], fecha: lun, duracionMin: 30 }, '09:05'), false, 'solo múltiplos de 15 min');
});

test('zona horaria La Paz: sabado usa clave "sab" y conversión UTC-4 consistente (RN-15)', () => {
  assert.equal(diaSemanaLocal('2026-11-21'), 'sab');
  assert.equal(diaSemanaLocal('2026-11-16'), 'lun');
  const u = aUtc('2026-11-16', '09:00');
  assert.equal(u.toISOString(), '2026-11-16T13:00:00.000Z');
  const l = aLocal(u);
  assert.deepEqual({ fecha: l.fecha, hora: l.hora }, { fecha: '2026-11-16', hora: '09:00' });
});

