  api('POST', '/api/v1/citas', { token: soliToken, headers: { 'idempotency-key': 'cp-full-10-conc-b-0001' }, body: { servicio_id: servicioId, profesional_id: profeId, fecha: hoy, hora_inicio: primerSlot || HORA_HOY } }),
