let citaCancel = reserva2.json?.cita?.id || null;
if (!citaCancel) {
  const nueva = await api('POST', '/api/v1/citas', {
    token: soliToken,
    headers: { 'idempotency-key': 'cp-full-10-cancel-0001' },
    body: { servicio_id: servicioId, profesional_id: profeId, fecha: hoy, hora_inicio: primerSlot || HORA_HOY },
  });
