    token: adminToken,
    headers: { 'idempotency-key': 'cp-full-10-cancel-op-0001' },
    body: { justificacion: 'Cancelacion de verificacion CP-FULL-10' },
  });
  linea('15. Cancelación con justificación (RF-018/019, CA-005)', `PUT /api/v1/citas/${citaCancel}/cancelar -> ${cancelar.status}\n${JSON.stringify(cancelar.json)}`);
}

